import{_ as t,o as a,c as o,ae as n}from"./chunks/framework.DQC_QtFV.js";const b=JSON.parse('{"title":"Environment variables (.env)","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/env.md","filePath":"en/guide/env.md","lastUpdated":1793162416000}'),d={name:"en/guide/env.md"};function r(s,e,i,h,l,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="environment-variables-env" tabindex="-1">Environment variables (.env) <a class="header-anchor" href="#environment-variables-env" aria-label="Permalink to &quot;Environment variables (.env)&quot;">​</a></h1><p><code>.env</code> is a plain env file next to <code>compose.yaml</code>: <code>KEY=value</code> lines and <code>#</code> comments, nothing else. Copy <code>.env.example</code> to <code>.env</code> and fill it in. These are all of the variables.</p><h2 id="required" tabindex="-1">Required <a class="header-anchor" href="#required" aria-label="Permalink to &quot;Required&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>What it is</th></tr></thead><tbody><tr><td><code>CONSOLE_PASSWORD</code></td><td>the panel&#39;s password. It is the only thing standing between the internet and your panel, so make it long</td></tr><tr><td><code>DRIVER_TOKEN</code></td><td>one of the internal tokens; the driver refuses to start without it. The console and the bot use it to call the driver</td></tr><tr><td><code>BOT_TOKEN</code></td><td>one of the internal tokens; the console holds it and never hands it to the browser</td></tr><tr><td><code>SANDBOX_EXEC_TOKEN</code></td><td>one of the internal tokens; the bot uses it to call the sandbox, where only root can read it</td></tr></tbody></table><p>Generate the three tokens with <code>openssl rand -hex 32</code>. They never leave the stack: each service gets only the ones it needs.</p><h2 id="qq-source-exactly-one" tabindex="-1">QQ source: exactly one <a class="header-anchor" href="#qq-source-exactly-one" aria-label="Permalink to &quot;QQ source: exactly one&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>What it is</th></tr></thead><tbody><tr><td><code>QQ_DEB_URL</code></td><td>the URL the <code>qq</code> container downloads the pinned build from. Leave it empty and mount a deb instead to install from a file</td></tr></tbody></table><p>With both set, or with neither, the container refuses to start and says so. Details on <a href="./first-start.html">First start</a>.</p><h2 id="optional" tabindex="-1">Optional <a class="header-anchor" href="#optional" aria-label="Permalink to &quot;Optional&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>What it is</th></tr></thead><tbody><tr><td><code>PI_OFFLINE</code></td><td><code>0</code></td><td><code>1</code> disables pi&#39;s model-catalog fetch, for fully offline runs</td></tr><tr><td><code>KEYX_TIMEOUT_S</code></td><td><code>900</code></td><td>how long the first boot waits for the database-key extraction. Measured at up to about 8 minutes, so raise it on a slow machine; a timeout is not fatal, the driver keeps watching</td></tr><tr><td><code>PERSONAL_BOT_TAG</code></td><td>empty (<code>latest</code>)</td><td>the image tag to run. Empty means the newest release; a tag such as <code>v2026.1025.0</code> pins one</td></tr></tbody></table><h2 id="the-assistant-s-own-settings-are-not-environment-variables" tabindex="-1">The assistant&#39;s own settings are not environment variables <a class="header-anchor" href="#the-assistant-s-own-settings-are-not-environment-variables" aria-label="Permalink to &quot;The assistant&#39;s own settings are not environment variables&quot;">​</a></h2><p>Which model, who may talk to it, what it may remember, which domains its commands may reach, how messages are batched, how the queue orders - all of that lives in the <a href="./console/">console</a>, takes effect as you change it, and needs neither an <code>.env</code> edit nor a rebuild.</p><p><code>compose.yaml</code> also carries two screen variables (<code>SCREEN_W</code>, <code>SCREEN_H</code>, 1280x800 by default) that set the live view&#39;s size; changing them means changing <code>compose.yaml</code> and rebuilding the qq image.</p>',13)])])}const u=t(d,[["render",r]]);export{b as __pageData,u as default};
